// tools/export_moves.js: docs/move_rework_holding/move-conversions-described.json -> js/data/moves-generated.js
// Usage: node tools/export_moves.js           write the generated file
//        node tools/export_moves.js --check   exit 1 if the file on disk differs from a fresh export (hand-edit guard)
// Facts are exported verbatim, minus authoring-only fields. Defaults are NOT dropped yet (shortcut: ~31 KB for 63
// moves, so the size win is small; drop them once the move list grows and the resolver applies grammar defaults).
const fs = require('fs'), path = require('path');
const root = path.resolve(__dirname, '..');
const SRC = path.join(root, 'docs/move_rework_holding/move-conversions-described.json');
const OUT = path.join(root, 'js/data/moves-generated.js');
const DROP = new Set(['kind', 'feel', 'reviewStatus', 'note']);   // authoring-only; they stay in the source JSON
const U = '@UNLIMITED@';                                            // placeholder swapped for the constant below

const strip = v => Array.isArray(v) ? v.map(strip)
  : v && typeof v === 'object' ? Object.fromEntries(Object.entries(v).filter(([k]) => !DROP.has(k)).map(([k, x]) => [k, strip(x)]))
  : v === 'UNLIMITED' ? U : v;

const moves = JSON.parse(fs.readFileSync(SRC, 'utf8')).moves;
const ids = Object.keys(moves);
const body = ids.map(id => '    ' + JSON.stringify(id) + ': ' + JSON.stringify(strip(moves[id])).replace(new RegExp('"' + U + '"', 'g'), 'U')).join(',\n');
const out = `/* GENERATED by tools/export_moves.js from docs/move_rework_holding/move-conversions-described.json (${ids.length} moves).
 * DO NOT EDIT BY HAND: change the source JSON and re-run the export. Raw move facts only; the resolver layers
 * formulas, presets and overrides on top. Needs move-attributes.js loaded first (UNLIMITED).
 * GROUNDWORK: not listed in dev.html and read by nothing in the game yet. */
(() => {
  const U = G.MoveAttrs.UNLIMITED;
  G.MoveData = {
${body}
  };
})();
`;

if (process.argv.includes('--check')) {
  const disk = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8').replace(/\r\n/g, '\n') : '';
  if (disk !== out) { console.log('STALE js/data/moves-generated.js: run node tools/export_moves.js'); process.exit(1); }
  console.log('moves-generated.js is current (' + ids.length + ' moves)');
} else {
  fs.writeFileSync(OUT, out);
  console.log('wrote js/data/moves-generated.js: ' + ids.length + ' moves, ' + (out.length / 1024).toFixed(1) + ' KB');
}
